Duration Floor(const Duration d, const Duration unit) {
  const absl::Duration td = Trunc(d, unit);
  return td <= d ? td : td - unit;
}

Duration Ceil(const Duration d, const Duration unit) {
  const absl::Duration td = Trunc(d, unit);
  return td >= d ? td : td + unit;
}

edits.new:
Duration Floor(const Duration d, const Duration unit) {
  const absl::Duration td = Trunc(d, unit);
  if (td <= d) return td;
  return unit < ZeroDuration() ? td + unit : td - unit;
}

Duration Ceil(const Duration d, const Duration unit) {
  const absl::Duration td = Trunc(d, unit);
  if (td >= d) return td;
  return unit < ZeroDuration() ? td - unit : td + unit;
}
